D.match=[{"g": "m0", "e": "[[y = x^2 - 4]]", "r": "<b style=\"color:#15803d\">➕ חיובית:</b> [[x &lt; -2]] או [[x > 2]]<br><b style=\"color:#b91c1c\">➖ שלילית:</b> [[-2 &lt; x &lt; 2]]", "h1": "😊 מחייכת וחותכת ב-[[-2]] ו-[[2]] ← מחפשים [[a > 0]] ואפסים [[±2]].", "h2": "מחייכת: מעל ציר x <b>מחוץ</b> לאפסים, מתחת <b>בין</b> האפסים."}, {"g": "m1", "e": "[[y = (x - 4)^2]]", "r": "<b style=\"color:#15803d\">➕ חיובית:</b> לכל [[x ≠ 4]]<br><b style=\"color:#b91c1c\">➖ שלילית:</b> אף x", "h1": "🎯 נוגעת בציר x רק ב-[[x = 4]] ← בריבוע שלם [[(x - 4)^2]] יש אפס אחד.", "h2": "הגרף אף פעם לא יורד מתחת לציר x – רק נוגע ב-4."}, {"g": "m2", "e": "[[y = 4 - x^2]]", "r": "<b style=\"color:#15803d\">➕ חיובית:</b> [[-2 &lt; x &lt; 2]]<br><b style=\"color:#b91c1c\">➖ שלילית:</b> [[x &lt; -2]] או [[x > 2]]", "h1": "☹️ בוכה (מקסימום) וחותכת ב-[[±2]] ← [[a &lt; 0]]: המינוס על [[x^2]].", "h2": "בוכה: מעל ציר x <b>בין</b> האפסים – הפוך מהמחייכת."}, {"g": "m3", "e": "[[y = x^2 - 4x]]", "r": "<b style=\"color:#15803d\">➕ חיובית:</b> [[x &lt; 0]] או [[x > 4]]<br><b style=\"color:#b91c1c\">➖ שלילית:</b> [[0 &lt; x &lt; 4]]", "h1": "😊 חותכת ב-0 וב-4 ← [[x(x - 4) = 0]].", "h2": "אפסים 0 ו-4, מחייכת ← שלילית בין 0 ל-4."}, {"g": "m4", "e": "[[y = x^2 - 4x + 3]]", "r": "<b style=\"color:#15803d\">➕ חיובית:</b> [[x &lt; 1]] או [[x > 3]]<br><b style=\"color:#b91c1c\">➖ שלילית:</b> [[1 &lt; x &lt; 3]]", "h1": "😊 חותכת ב-1 וב-3 ← [[(x - 1)(x - 3) = x^2 - 4x + 3]].", "h2": "מחייכת, אפסים 1 ו-3 ← מתחת לציר בין 1 ל-3."}, {"g": "m5", "e": "[[y = -(x + 1)(x - 3)]]", "r": "<b style=\"color:#15803d\">➕ חיובית:</b> [[-1 &lt; x &lt; 3]]<br><b style=\"color:#b91c1c\">➖ שלילית:</b> [[x &lt; -1]] או [[x > 3]]", "h1": "☹️ בוכה, חותכת ב-[[-1]] וב-3 ← סוגריים [[(x + 1)]] ו-[[(x - 3)]] עם מינוס לפני.", "h2": "בוכה ← חיובית בין האפסים [[-1]] ו-3."}, {"g": "m6", "e": "[[y = x^2 + 2]]", "r": "<b style=\"color:#15803d\">➕ חיובית:</b> לכל x<br><b style=\"color:#b91c1c\">➖ שלילית:</b> אף x", "h1": "😊 הקודקוד [[(0, 2)]] מעל ציר x ← אין אפסים ← [[x^2 + 2]].", "h2": "כל הגרף מעל ציר x ← חיובית תמיד."}, {"g": "m7", "e": "[[y = x^2 + 4x]]", "r": "<b style=\"color:#15803d\">➕ חיובית:</b> [[x &lt; -4]] או [[x > 0]]<br><b style=\"color:#b91c1c\">➖ שלילית:</b> [[-4 &lt; x &lt; 0]]", "h1": "😊 חותכת ב-[[-4]] וב-0 ← [[x(x + 4) = 0]].", "h2": "אפסים [[-4]] ו-0, מחייכת ← שלילית ביניהם."}, {"g": "z0", "e": "[[y = x^2 - 1]]", "r": "🦋 זוגית · סימטרית ל<b>ציר y</b><br>[[f(-1) = f(1) = 0]]", "h1": "מחייכת עם קודקוד [[(0, -1)]] על ציר y.", "h2": "מקפלים על ציר y – שני הצדדים נופלים זה על זה.", "q2": "🧩 שלב 2: זוגית, אי-זוגית או אף אחת – ולאיזה ציר או נקודה היא סימטרית?"}, {"g": "z1", "e": "[[y = x^3]]", "r": "🔄 אי-זוגית · סימטרית ל<b>ראשית</b><br>[[f(2) = 8]], [[f(-2) = -8]]", "h1": "צורת S פשוטה שעוברת ב-[[(0, 0)]], בלי \"גבעות\".", "h2": "מסובבים סביב [[(0, 0)]] – הגרף חוזר לעצמו.", "q2": "🧩 שלב 2: זוגית, אי-זוגית או אף אחת – ולאיזה ציר או נקודה היא סימטרית?"}, {"g": "z2", "e": "[[y = x^3 - 3x]]", "r": "🔄 אי-זוגית · סימטרית ל<b>ראשית</b><br>[[f(1) = -2]], [[f(-1) = 2]]", "h1": "S עם גבעה ועמק, עוברת ב-[[(0, 0)]].", "h2": "סיבוב סביב הראשית: הגבעה משמאל ← העמק מימין.", "q2": "🧩 שלב 2: זוגית, אי-זוגית או אף אחת – ולאיזה ציר או נקודה היא סימטרית?"}, {"g": "z3", "e": "[[y = (x - 1)^2]]", "r": "❌ אף אחת · ציר הסימטריה [[x = 1]]<br>(לא ציר y)", "h1": "הקודקוד ב-[[x = 1]], לא על ציר y ← [[(x - 1)^2]].", "h2": "הקודקוד לא על ציר y ← אין מראה, ואין סיבוב.", "q2": "🧩 שלב 2: זוגית, אי-זוגית או אף אחת – ולאיזה ציר או נקודה היא סימטרית?"}];
